  CreateOrganizationInput,
  DeleteOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Organization, OrganizationSummary } from "@/types/organization";

/**
 * Creates an organization and everything it cannot exist without: the owner's
 * membership row and a subscription. Sign-up and "create another workspace"
 * both land here, which is why it takes a bare `ownerId` rather than an
 * `Actor` — there is no membership to build one from yet.
 */
export async function createOrganization(
  ownerId: UserId,
  input: CreateOrganizationInput,
): Promise<Organization> {
  assertValidSlug(input.slug);

  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);

  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);

  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
  await usageRepo.recomputeUsage(org.id);

  await emit("member.joined", {
    ...envelope(org.id, ownerId),
    memberId: owner.id,
    userId: ownerId,
    role: owner.role,
  });

  return org;
}

export async function updateOrganization(
  actor: Actor,
  input: UpdateOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const updated = await orgRepo.updateOrg(input.orgId, input);

  // Settings changes are audited directly: the event bus has no
  // `organization.updated` key, and inventing one would widen the contract.
  await record(input.orgId, "organization.updated", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `${updated.name} settings updated`,
  });

  return updated;
}

/**
 * Deletion is a soft delete guarded by a typed confirmation, the same shape
 * GitHub uses: the caller has to retype the slug.
 */
export async function deleteOrganization(
  actor: Actor,
  input: DeleteOrganizationInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:delete", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug !== input.confirmSlug) {
    throw new Error("The confirmation does not match this organization's slug");
  }

  return orgRepo.archiveOrg(input.orgId);
}

/** The header/shell payload: the org plus the counters the sidebar shows. */
export async function getOrganizationSummary(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationSummary> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const organization = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  return {
    organization,
    usage: await usageRepo.getUsage(orgId),
    memberCount: await memberRepo.countActiveMembers(orgId),
    projectCount: await projectRepo.countProjects(orgId),
  };
}

/** The org switcher's list; no `Actor` exists until one is chosen. */
export async function listOrganizationsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  return orgRepo.listOrgsForUser(userId);
}

export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}
/** Token-bucket refill and exhaustion. */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { getPlanLimits } from "@/config/plan-limits";
import {
  RATE_LIMIT_BUCKETS,
  consumeRateLimit,
  getBucketConfig,
  resetRateLimits,
  setOrgPlan,
} from "@/lib/rate-limit";
import { ORG_A, ORG_B } from "../helpers/factories";

beforeEach(() => {
  resetRateLimits();
  vi.useFakeTimers();
  vi.setSystemTime(new Date("2026-03-15T12:00:00.000Z"));
});

afterEach(() => {
  vi.useRealTimers();
});

describe("lib/rate-limit", () => {
  it("returns the declared config for a known bucket", () => {
    expect(getBucketConfig("member:invite")).toEqual(
      RATE_LIMIT_BUCKETS["member:invite"],
    );
  });

  it("falls back to a default config for an unknown bucket", () => {
    const config = getBucketConfig("something:new");
    expect(config.capacity).toBeGreaterThan(0);
    expect(config.refillPerMinute).toBeGreaterThan(0);
  });

  it("allows a first request and reports the remaining tokens", async () => {
    const verdict = await consumeRateLimit(ORG_A, "member:invite");
    expect(verdict.allowed).toBe(true);
    expect(verdict.remaining).toBe(19);
  });

  it("exhausts the bucket and then refuses", async () => {
    const capacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < capacity; i += 1) {
      expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(true);
    }

    const denied = await consumeRateLimit(ORG_A, "auth:password-reset");
    expect(denied.allowed).toBe(false);
    expect(denied.remaining).toBe(0);
  });

  it("refills over time at the declared rate", async () => {
    const { capacity, refillPerMinute } = getBucketConfig("auth:password-reset");
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ORG_A, "auth:password-reset");
    }
    expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(false);

    vi.advanceTimersByTime(2 * 60_000);
    const after = await consumeRateLimit(ORG_A, "auth:password-reset");
    expect(after.allowed).toBe(true);
    expect(after.remaining).toBe(2 * refillPerMinute - 1);
  });

  it("never refills past capacity", async () => {
    await consumeRateLimit(ORG_A, "member:invite");
    vi.advanceTimersByTime(24 * 60 * 60_000);

    const verdict = await consumeRateLimit(ORG_A, "member:invite");
    expect(verdict.remaining).toBe(getBucketConfig("member:invite").capacity - 1);
  });

  it("charges the supplied cost", async () => {
    const verdict = await consumeRateLimit(ORG_A, "member:invite", 5);
    expect(verdict.allowed).toBe(true);
    expect(verdict.remaining).toBe(15);
  });

  it("refuses a cost larger than the bucket without spending tokens", async () => {
    const denied = await consumeRateLimit(ORG_A, "auth:password-reset", 999);
    expect(denied.allowed).toBe(false);
    expect(denied.remaining).toBe(getBucketConfig("auth:password-reset").capacity);
  });

  it("keeps buckets separate per org and per key", async () => {
    const capacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ORG_A, "auth:password-reset");
    }

    expect((await consumeRateLimit(ORG_A, "auth:password-reset")).allowed).toBe(false);
    expect((await consumeRateLimit(ORG_B, "auth:password-reset")).allowed).toBe(true);
    expect((await consumeRateLimit(ORG_A, "member:invite")).allowed).toBe(true);
  });

  it("scales capacity with the org's plan quota rather than hard-coding it", async () => {
    setOrgPlan(ORG_B, "growth");
    const growth = await consumeRateLimit(ORG_B, "member:invite");
    const free = await consumeRateLimit(ORG_A, "member:invite");

    expect(getPlanLimits("growth").apiRequestsPerHour).toBeGreaterThan(
      getPlanLimits("free").apiRequestsPerHour,
    );
    expect(growth.remaining).toBeGreaterThan(free.remaining);
  });

  it("reports a resetAt in the future when the bucket is empty", async () => {
    const capacity = getBucketConfig("auth:password-reset").capacity;
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ORG_A, "auth:password-reset");
    }

    const denied = await consumeRateLimit(ORG_A, "auth:password-reset");
    expect(new Date(denied.resetAt).getTime()).toBeGreaterThan(Date.now());
  });
});

